import sys, time, random
sys.path.insert(0,'/workspace/deps')
sys.path.insert(0,'/tmp/dev')
import networkx as nx
from mcf import Flow

def build(NR,NO,PAIRS,seed,offercap=1,costmax=10**9,nq=4):
    random.seed(seed)
    N=2+2*nq+NR+NO
    S=0;T=1
    def rq(i): return 2+i
    def oq(i): return 2+nq+i
    def R(i): return 2+2*nq+i
    def O(i): return 2+2*nq+NR+i
    f=Flow(N)
    for i in range(nq):
        if i==0: f.add(S,rq(0),4096,0)
        else: f.add(rq(i-1),rq(i),4096,0)
    for i in range(nq):
        if i==0: f.add(oq(0),T,4096,0)
        else: f.add(oq(i),oq(i-1),4096,0)
    for i in range(NR): f.add(rq(i%nq), R(i), 1, 0)
    for i in range(NO): f.add(O(i), oq(i%nq), offercap, 0)
    pairs=set()
    while len(pairs)<PAIRS: pairs.add((random.randrange(NR), random.randrange(NO)))
    costs=[random.randrange(costmax) for _ in range(NO)]
    for a,b in pairs: f.add(R(a), O(b), 1, costs[b])
    return f,S,T,NR,NO,R,O,costs

def nxbuild(NR,NO,PAIRS,seed,offercap=1,costmax=10**9,nq=4):
    f,S,T,NR,NO,R,O,costs=build(NR,NO,PAIRS,seed,offercap,costmax,nq)
    G=nx.DiGraph()
    for u in range(f.n):
        for ei in f.graph[u]:
            if ei%2==0:
                G.add_edge(u,f.to[ei],capacity=f.cap[ei],weight=f.cst[ei])
    return G,S,T,f,R,O,costs

for (NR,NO,PAIRS,seed,oc,cm) in [(200,400,6000,1,1,10**9),(1000,2000,60000,2,1,10**9),(1000,2000,60000,3,4,20),(4000,8000,262144,4,8,100)]:
    f,S,T,*_=build(NR,NO,PAIRS,seed,oc,cm)
    t=time.time(); tot,cost=f.solve(S,T); dt=time.time()-t
    G,S2,T2,f2,R,O,costs=nxbuild(NR,NO,PAIRS,seed,oc,cm)
    t=time.time()
    mf=nx.maximum_flow_value(G,S2,T2)
    H=nx.DiGraph(G); H.add_node(S2,demand=-mf); H.add_node(T2,demand=mf)
    c2,fd=nx.network_simplex(H)
    dt2=time.time()-t
    print(f'NR={NR} NO={NO} pairs={PAIRS} cap={oc} costmax={cm}: primal-dual flow={tot} cost={cost} t={dt:.2f} | nx flow={mf} cost={c2} t={dt2:.2f} match={(tot,cost)==(mf,c2)}', flush=True)
PYEOF
